      "name": "Synumanus",
      "url": "https://www.synumanus.fr/",
      "logo": "https://www.synumanus.fr/assets/logo-synumanus-512.png",
      "email": "contact@synumanus.fr",
      "description": "Applications mobiles, web et automatisations sur mesure pour les TPE, PME et entrepreneurs.",
      "address": {
        "@type": "PostalAddress",
        "addressLocality": "Neuilly-sur-Seine",
        "postalCode": "92200",
        "addressCountry": "FR"
      },
      "areaServed": "FR",
      "knowsAbout": [
        "Applications mobiles",
        "Applications web métier",
        "Automatisation",
        "Accessibilité numérique"
      ]
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Combien coûte une application ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Le prix dépend du nombre d’écrans, des règles métier, des connexions à vos outils et des plateformes visées. Nous n’affichons pas de tarif : le devis est établi après le cadrage, sur un périmètre précis, pour éviter les mauvaises surprises."
          }
        },
        {
          "@type": "Question",
          "name": "Combien de temps faut-il ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Comptez en général 2 à 4 mois pour une première version utilisable. Vous voyez une version testable toutes les deux semaines."
          }
        },
        {
          "@type": "Question",
          "name": "Je n’y connais rien en technique, est-ce un problème ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Non. Vous connaissez votre métier, c’est ce qui compte. Nous traduisons vos besoins et expliquons chaque choix en langage simple."
          }
        },
        {
          "@type": "Question",
          "name": "Que se passe-t-il après la livraison ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nous proposons une maintenance : corrections, mises à jour iOS et Android, évolutions. Vous restez propriétaire de tout et libre de changer de prestataire."
          }
        },
        {
          "@type": "Question",
          "name": "Où êtes-vous situés ?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Synumanus est installée dans les locaux des Tricolores, à Neuilly-sur-Seine. Nous vous recevons sur rendez-vous et travaillons aussi à distance partout en France."
          }
        }
      ]
    }
  ]
}
